import re,os,glob,collections
def decls(f):
    ns=[]; out=set()
    for l in open(f):
        m=re.match(r'namespace\s+([\w.]+)',l)
        if m: ns.append(m.group(1)); continue
        if re.match(r'end\s+[\w.]+',l) and ns:
            nm=re.match(r'end\s+([\w.]+)',l).group(1)
            if ns and ns[-1]==nm: ns.pop()
            continue
        m=re.match(r'(?:@\[[^\]]*\]\s*)?(?:noncomputable\s+)?(?:protected\s+)?(?:private\s+)?(theorem|lemma|def|abbrev|instance|structure|class)\s+([\w.₀-₉\'!?]+)',l)
        if m and m.group(2):
            out.add('.'.join(ns+[m.group(2)]))
    return out
ledger=set(); ledfiles=glob.glob('AlgebraicJacobian/RiemannRoch/Ledger/*.lean')
for f in ledfiles: ledger |= decls(f)
other=collections.defaultdict(list)
for f in glob.glob('AlgebraicJacobian/**/*.lean',recursive=True):
    if '/Ledger/' in f: continue
    for d in decls(f): other[d].append(f)
coll=sorted(set(ledger) & set(other))
print("Ledger decls:",len(ledger)," other decls:",len(other))
print("COLLISIONS:",len(coll))
for c in coll[:25]: print("  ",c,"<-",other[c][0])
EOF
